import { isDeepStrictEqual } from 'node:util';
import { pathToFileURL } from 'node:url';
import path from 'node:path';
const dir = process.argv[2];
const load = (n) => import(pathToFileURL(path.join(dir, n + '.mjs')).href);
const O = await load('orig'), C = await load('cand'), A = await load('alt');
const alpha = ['1','2','s','t','T','S','h','A','a','B','b','_','-','.',' '];
let total=0, candBad=[], altBad=[];
const rec = (prefix, depth) => {
  total++;
  const o = O.tokens(prefix);
  if (!isDeepStrictEqual(o, C.tokens(prefix)) && candBad.length<5) candBad.push(prefix);
  if (!isDeepStrictEqual(o, A.tokensNative(prefix)) && altBad.length<5) altBad.push(prefix);
  if (depth===0) return;
  for (const c of alpha) rec(prefix + c, depth-1);
};
rec('', 5);
console.log('strings checked:', total, 'cand mismatches (first 5):', candBad, 'native-alt mismatches (first 5):', altBad);
for (const s of ['1st','21ST','3rd','4th','2nd','Hello1st']) console.log(JSON.stringify(s), JSON.stringify(O.tokens(s)), JSON.stringify(C.tokens(s)), JSON.stringify(A.tokensNative(s)));
EOF
node exhaust.mjs "$S" 2>&1 | tail -12

